\[\operatorname{proj}_{\mathbf{w}} \mathbf{v} = \frac{\mathbf{v} \cdot \mathbf{w}}{\|\mathbf{w}\|^2} \mathbf{w} = \begin{pmatrix} 1 \\ 0 \\ -3 \end{pmatrix}.\][asy]
